/** Small formatting helpers shared by the generators. */

export const GENERATED_NOTICE =
  "GENERATED by @chicman/design-tokens — do not edit by hand.\n" +
  "Source: packages/design-tokens/src/tokens.ts. Regenerate with `pnpm tokens`.";

/** `bg-base` → `bgBase`, `control-sm` → `controlSm`. */
export function camelCase(name: string): string {
  return name.replace(/-([a-z0-9])/g, (_, c: string) => c.toUpperCase());
}

/** `displayLarge` → `display-large`. */
export function kebabCase(name: string): string {
  return name.replace(/[A-Z]/g, (c) => `-${c.toLowerCase()}`);
}

/** px → rem string (16px root), e.g. 44 → `2.75rem`. */
export function rem(px: number): string {
  return `${Number((px / 16).toFixed(4))}rem`;
}

/** Number literal without trailing zeros, e.g. 0.5, 16. */
export function num(value: number): string {
  return String(Number(value.toFixed(4)));
}

/** Radius key → Dart identifier: `2xl` → `xxl`, `3xl` → `xxxl`. */
export function dartRadiusName(key: string): string {
  const match = /^(\d)xl$/.exec(key);
  return match ? `${"x".repeat(Number(match[1]) - 1)}xl` : key;
}

/** `#F4F7FB` → `0xFFF4F7FB`. */
export function dartColor(hex: string): string {
  const value = hex.replace("#", "").toUpperCase();
  if (!/^[0-9A-F]{6}$/.test(value)) {
    throw new Error(`Invalid color token "${hex}" (expected #RRGGBB).`);
  }
  return `0xFF${value}`;
}

export const WEIGHT_FILE_SUFFIX: Record<number, string> = {
  400: "Regular",
  500: "Medium",
  600: "SemiBold",
  700: "Bold",
};

function channels(hex: string): [number, number, number] {
  const value = hex.replace("#", "");
  return [0, 2, 4].map((i) => parseInt(value.slice(i, i + 2), 16)) as [number, number, number];
}

/** Opaque result of drawing `fg` at `alpha` over `bg`. */
export function blend(fg: string, bg: string, alpha: number): string {
  const f = channels(fg);
  const b = channels(bg);
  const mixed = f.map((c, i) => Math.round(alpha * c + (1 - alpha) * (b[i] ?? 0)));
  return `#${mixed.map((c) => c.toString(16).padStart(2, "0")).join("")}`;
}

/** WCAG 2.x contrast ratio between two opaque colors. */
export function contrastRatio(a: string, b: string): number {
  const luminance = (hex: string) => {
    const [r, g, bl] = channels(hex).map((c) => {
      const s = c / 255;
      return s <= 0.03928 ? s / 12.92 : ((s + 0.055) / 1.055) ** 2.4;
    }) as [number, number, number];
    return 0.2126 * r + 0.7152 * g + 0.0722 * bl;
  };
  const [hi, lo] = [luminance(a), luminance(b)].sort((x, y) => y - x) as [number, number];
  return (hi + 0.05) / (lo + 0.05);
}
